story=[]
def P(text,style='body'):return Paragraph(escape(text),styles[style])
def add(text,style='body'):story.append(P(text,style))
def heading(n,title):add(n.upper(),'eyebrow');add(title,'h1')
def section(title,items):add(title,'h2');steps(items)
def steps(items):
 for i,text in enumerate(items,1):
  t=Table([[P(f'{i:02d}','mono'),P(text)]],colWidths=[9*mm,167*mm]);t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),4)]));story.append(t)
def note(text):
 t=Table([[P(text)]],colWidths=[176*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('BOX',(0,0),(-1,-1),.5,line),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.append(t)
def table(rows,widths=None):
 t=Table([[P(str(v),'small' if i else 'mono') for v in row] for i,row in enumerate(rows)],colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),pale),('LINEBELOW',(0,0),(-1,0),.7,line),('LINEBELOW',(0,1),(-1,-1),.3,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t)
def pic(path,w=176*mm,maxh=108*mm):
 from PIL import Image as PIL
 p=R/path
 if not p.exists():return
 with PIL.open(p) as image:iw,ih=image.size
 h=w*ih/iw
 if h>maxh:w*=maxh/h;h=maxh
 story.append(Image(str(p),width=w,height=h,hAlign='LEFT'))
def new():story.append(PageBreak())
add('ESP32-S3 / A3-120 / BUILD & SERVICE MANUAL','eyebrow');add('Connect.\nMeasure.\nCalibrate.','title')
add('Sensor installation, connection diagnosis and ECU Studio configuration','h2');add('120 × 120 mm through-hole carrier • Plug-in ESP32-S3 DevKitC-1 • Revision A3-120 / 30 October 2026')
pic('reports/a3/pcb-3d.png',maxh=90*mm)
note('Engineering prototype and bench monitor. All actuator commands remain OFF. This package does not implement a complete replacement engine ECU and has not been tested on a car. CAD checks and software tests do not establish surge immunity, EMC, splash resistance, emissions compliance or mechanical fit.')
section('Read in this order',['Identify the board revision, connector orientation and power arrangement.','Assemble and test the unpowered board, then qualify the power rails on a current-limited bench supply.','Use the individual sensor chapters and identical web guides. Enter the real sensor curves, then verify independent reference points.','Fit the insulating tray, shield bonds and splash gasket. Check the printed fit and controlled splash resistance before choosing any installation location.'])
new();heading('01 / scope','What this design supports')
table([['Implemented','Outside this release'],['Six conditioned 0-5 V analog inputs, 12-bit SPI ADC, diagnostic conversion and filtering.','Fuel/ignition scheduling, fuel maps, tune commissioning, knock control and engine operation.'],['Two conditioned 5 V Hall inputs, missing-tooth crank bench decoder and cam edge counts.','Raw VR sensors, full 720° phase decoding, every OEM trigger pattern.'],['500 kbit/s listen-only CAN frame counts.','OEM CAN messages, dashboard, immobilizer, automatic transmission or air-conditioning integration.'],['External wideband-controller analog input and buffered post-catalyst measurement.','Raw wideband drive/heater control, catalyst efficiency diagnostics and OBD emissions readiness.'],['Design provisions for surge clamping, reverse polarity, filtering, ground plane and shield return.','Verified ISO automotive transient/EMC qualification or universal compatibility.']],[88*mm,88*mm])
section('Universal carrier, vehicle-specific interface',['There is no universal OEM ECU connector or sensor pinout. Use a documented adapter harness with verified cavity numbers for the specific vehicle.','A naturally aspirated engine with a catalytic converter can still require electronic throttle, immobilizer and network functions absent here. Keep the original ECU in service until an actual replacement system is separately engineered and qualified.','Do not share sensor signals with another ECU until input loading, grounding and failure behavior have been reviewed. Do not remove or emulate catalyst monitoring.'])
section('Basic bench kit',['Current-limited regulated 12 V supply, suitable 1 A external fuse and an accessible disconnect.','Digital multimeter, magnifier, soldering iron and appropriate leaded soldering tools. Use a properly referenced or isolated oscilloscope for digital edges and noise.','3.3 V UART adapter; do not use 5 V TTL, RS-232 levels or an adapter power lead.','A trusted low-voltage signal/reference source and sensor-specific mechanical/reference tools. Never use a test lamp on a signal input.'])
new();heading('02 / board assembly','Build and inspect the carrier')
steps(['Use hardware/a3-compact, not the larger A2 board. The copper outline is 120 × 120 mm, six copper layers, 1.6 mm nominal FR-4. Check the final ERC/DRC and audit reports before ordering.','All carrier component joints are plated through-hole. Fit ordinary axial resistors upright on the indicated 2.54 mm pitch; R150 stays horizontal. Observe the vertical diode polarity drawing, not just the direction of a bent lead.','Fit low components first, then capacitors, direct-solder DIP ICs, TO-220 devices and connectors. IC sockets are not required. Leave DNP optional pull-ups absent unless the specific sensor needs them.','Fit the two 1 × 22 female headers for the specified 44-pin ESP32-S3 DevKitC-1 v1.1. Use a known straight header jig while soldering. Do not substitute a similar-looking 30/38-pin ESP32 or assume every S3 board has the same spacing.','U1 is a purchased assembled Pololu D36V6F5 module. U3 is a purchased DevKit. These modules contain small factory-soldered parts; no bare S3 module or fine-pitch IC must be hand-soldered to the carrier.','Check IC notches, electrolytic polarity, diode bands, transistor pin order and live TO-220 tabs against the BOM and footprints. VNP35N07-E tabs are drain, not ground.','Inspect every joint, bridge and solder splash. Trim solder tails to at most 3 mm below the PCB, especially around H4. The printed H4 support includes reliefs matching R35 and D210.','With power disconnected, check for unintended rail shorts. Capacitors can make a continuity buzzer sound briefly; investigate sustained low resistance rather than relying on the buzzer alone.'])
note('The 120 mm layout is dense. A 3D model may omit an unavailable manufacturer model; the BOM, assembly drawing and native footprint pads define the build. DNP resistors are intentionally empty. Never infer that a pad is unused simply because a 3D body is absent.')
section('EMI provisions are an assembly requirement',['Retain the two continuous inner ground planes and the input filter/clamps. Keep sensor returns separate from the actuator power-return wiring.','Use twisted/shielded signal wiring as appropriate to the sensor. Keep it away from ignition coils, alternator wiring and relay/motor power.','Fit the conductive enclosure lining and short internal shield bonds, then cover the lining with the supplied dielectric tray and lid insulator. A plastic box alone is not an RF shield.'])
new();heading('02A / placement reference','Find the connector before wiring')
pic('reports/a3/connection-map.png',maxh=142*mm)
add('Connector locations from the native PCB, viewed from the top. Filled dots identify pin 1. Dimensions in the table are measured from the top-left PCB edge. The separate assembly.svg shows all component references and pads.','small')
table([['PCB location (mm)','Connection'],['Bottom row, left to right','J11 MAP / J12 TPS / J13 CLT / J14 IAT / J15 wideband / J16 buffered rear oxygen / J17 crank / J18 cam'],['Right edge, top to bottom','J9 injector low sides / J10 smart-coil logic / J8 relay coils'],['Top left / top right','J1 logic power / J19 power return'],['Left lower side','J7 CAN and H5 shield lug'],['Inside board','J2 UART at 61,58 / J3 interlock at 45,52.5 / J4 expansion at 57,73.5 / J20 shield at 98,97']],[60*mm,116*mm])
new();heading('03 / first power','Check power before sensors')
steps(g['services'][0]['checks'])
table([['Point','Meaning','Expected bench observation'],['TP1','GND','Reference for board checks.'],['TP2','VIN_PROT','Input after reverse diode, before input filter. At a 12 V source it is lower than the source by the diode drop.'],['TP3','+5V','Near nominal 5 V; verify under the intended sensor load.'],['TP4','+3V3','Near nominal 3.3 V; measure U6 VREF accurately for calibration.'],['TP5','SAFE_N','Near 3V3 when released; low during supervisor/watchdog reset.'],['TP6','RUN_5V','Low with J3 open and configuration monitor firmware.']],[22*mm,42*mm,112*mm])
section('If a rail is wrong',['Disconnect external harnesses and remove the DevKit, then locate the fault from the input toward the load. Check part value/orientation, the reverse diode and buck module pinout.','If 5 V collapses only with a sensor plugged in, check its actual pin order and current draw. The sensor rail PTC is shared, slow and temperature-dependent, not a precision electronic current limiter.','If 3V3 resets or overheats during Wi-Fi, inspect regulator dissipation, supply limits, capacitor/ESR requirements and current peaks. Software compilation does not verify power integrity.','Scope rails, SAFE_N and WDI together for repeating resets. Do not bypass the watchdog or supervisor. The monitor must keep servicing supervision while the web service runs.'])
note('J1 powers the ECU logic. Injector, smart-coil and relay power is external, fused and relay-switched. Do not connect an engine or real actuator harness during these checks.')
new();heading('04 / web service','Open ECU Studio')
steps(['Flash the compact_a3_web firmware using PlatformIO. Remove the DevKit from the carrier before powering its USB connector. Disconnect USB before reseating it in the unpowered carrier.','Keep J3 open and actuator harnesses disconnected. Attach J2 UART using 3.3 V logic at 115200 baud, 8-N-1, with no adapter power wire.','Power the carrier on a dry bench with the lid open. The service starts its own WPA2 AP, ECU-Service-XXXX. A new random password is printed in the UART boot log.','Join that AP and open http://192.168.4.1. No internet connection is needed. The AP is refused if J3 is closed at service startup. The conductive lining may block radio reception with the lid closed.','For a desktop preview, run python3 tools/web_server.py and open http://127.0.0.1:8765. The simulator is labelled NO HARDWARE and uses synthetic ADC values.'])
pic('reports/web/calibration.png',maxh=102*mm)
add('Screenshot: the actual offline UI running against the host simulator. Example numbers shown are not a vehicle calibration.','small')
section('Save and preserve settings',['Export a JSON backup before editing. Import stages a complete validated profile in the editor; it does not apply until saved.','Save validates all channels and commits NVS before changing the live conversion. Check the saved revision and status message.','A stale revision is rejected instead of overwriting another session. Export edits, reload the latest profile and reapply the intended change.','Unreadable or invalid saved storage activates defaults and blocks saving. Inspect UART and recover deliberately; firmware does not erase NVS automatically.'])
new();heading('05 / calibration','Configure a measured transfer curve')
steps(g['config_help'])
section('A practical calibration sequence',['Choose the sensor connector, verify supply/ground and compare displayed connector voltage with a trusted meter. Correct wiring before changing a curve.','Measure the actual ADC reference and enter it under Device & profile. A reference error changes every reconstructed voltage, including battery and sensor supply.','Choose voltage, two-point linear, voltage table or supported NTC beta. Enter physical units consistently. Use the real manufacturer curve or independently measured references, never the illustrative simulator curve.','Set an input fault window appropriate to that specific sensor. The default window is a starting point, not a diagnosis of every open/short. A legitimate endpoint can be zero volts on some interfaces.','Choose only as much readout filtering as necessary. Inspect raw voltage and the oscilloscope signal while checking wiring noise.','Save, verify several independent points across the intended range and only then mark the calibration confirmed. Record the sensor part number, curve source, pull-up and reference tools.'])
table([['Mode','Fields and behavior'],['Voltage','Reconstructs connector volts: ADC / 4095 × measured VREF / 0.6.'],['Linear','V0/Y0 and V1/Y1; ascending voltage endpoints. Physical values can increase or decrease. Outside the endpoints is a fault.'],['Table','2-16 ascending voltage/value pairs. Piecewise linear interpolation. No extrapolation beyond the table.'],['NTC beta','CLT/IAT only. R0, reference temperature, beta and actual physical pull-up. Uses measured sensor supply and 55 kohm load compensation.'],['Fault/filter','Fault checks use instantaneous voltage. The display filter smooths readout, not engine control.']],[30*mm,146*mm])
new();heading('06 / orientation','Sensor connector pin reference')
add('J11-J18 use the same PCB-side three-pin assignment. This does not establish the sensor-side wire colors or pin order. The mating view may be mirrored.')
table([['Connector','Signal / channel','Pin 1','Pin 2','Pin 3']]+[[s['connector'],s['name']+' / ADC '+str(s['adc_channel']),'GND','SENSOR_5V',s['signal']] for s in g['sensors']]+[['J17','Crank Hall / GPIO8','GND','SENSOR_5V','CRANK_RAW'],['J18','Cam Hall / GPIO9','GND','SENSOR_5V','CAM_RAW']],[24*mm,68*mm,21*mm,30*mm,33*mm])
section('Before connecting any sensor',g['general'])
note('Passive two-wire CLT/IAT NTCs use pins 1 and 3 only. Wideband-controller analog outputs use pins 1 and 3; pin 2 does not power a heater/controller. Raw VR and raw LSU sensors are unsupported without the appropriate external interface.')
for i,s in enumerate(g['sensors'],1):
 new();heading(f'07.{i} / {s["connector"]}',s['name'])
 table([['PIN 1','PIN 2','PIN 3'],s['pins']],[58.7*mm]*3)
 section('Mounting & routing',s['mount']);section('Connect & verify',s['checks']);section('Expected behavior',s['expected']);section('Fault tracing',s['faults']);add(s['circuit'],'small')
 if s['optional_pullup']:note(s['optional_pullup']+' is DNP by default. Fit it only after confirming the actual sensor topology and resistor value.')
for i,s in enumerate(g['triggers'],1):
 new();heading(f'08.{i} / {s["connector"]}',s['name']);table([['PIN 1','PIN 2','PIN 3'],s['pins']],[58.7*mm]*3);section('Mounting & routing',s['mount']);section('Connect & verify',s['checks']);section('Expected behavior',s['expected']);section('Fault tracing',s['faults']);add(s['circuit'],'small')
for i in range(0,len(g['services']),2):
 new();heading(f'09.{i//2+1} / service interfaces','Power, data and output connections')
 for s in g['services'][i:i+2]:section(s['connector']+' / '+s['title'],s['checks'])
new();heading('10 / live diagnosis','Trace a fault from the connector inward')
pic('reports/web/diagnostics.png',maxh=98*mm);add('Screenshot: host simulator with a deliberately shorted MAP input. Fault-injection controls are absent from the embedded firmware.','small')
steps(['Start with battery and sensor-rail measurements. If several channels fail together, inspect shared power/ground before adjusting every curve.','Compare pin 3 versus pin 1 at the connector with the web connector voltage. If those agree, inspect curve, units and reference settings.','If connector voltage is correct but ADC is wrong, check the named 22k/33k input divider, clamp polarity, filter capacitor, U6 reference and SPI connections. Do not inject an automotive battery voltage as a signal test.','If all ADC channels are stuck at zero/full scale, inspect U6 power/reference, chip select, MOSI/MISO/clock, solder bridges and the live ADC transfer status. A successful SPI transaction alone cannot prove sensor integrity.','For missing crank/cam counts, scope both raw and conditioned signals. Review pull-ups, Hall-versus-VR type, target geometry and air gap before blaming software.','Capture overflow is latched until power cycle. Find the signal/queue cause first; clearing a latch does not repair the source.','Export the diagnostic report with timestamp, profile revision and browser event history. Event history starts when that browser session starts. The export is not a persistent ECU flight recorder.','If the page disconnects, readings become stale. Check the AP, board supply and UART, then reconnect. Never use a frozen browser number as a live measurement.'])
new();heading('11 / printed enclosure','Install the board and shield')
pic('enclosure/a3/enclosure-3d.png',maxh=88*mm)
add('PCB: 120 × 120 mm. Printed base: 138 × 150 × 44 mm. Lid: 142 × 154 mm. Nominal assembled height: 47 mm. Cable glands add to the rear envelope.','small')
steps(['Print base, lid, insulating tray, lid insulator and insert coupon. Use a material/process suitable for the measured installation temperature, chemicals and vibration. Do not assume a printed case is suitable beside an exhaust or underhood heat source.','Test the coupon with the actual short M3 heat-set inserts before fitting them to the case. Four PCB supports take M3 short inserts; eight lid bosses and two internal shield bonds use the same insert type.','Install the internal base shield-bond insert and lining before the PCB blocks tool access. Keep the side-wall bond blind: do not drill through the outer wall.','Apply conductive lining following the templates. Keep it below and clear of the water-seal land. Bond seams with a suitable conductive method and use short broad internal bonds. The gasket is not an electrical bond.','Fit the insulating tray over the lining. Clear the support roots and internal bond boss. Ensure conductive foil cannot touch solder tails, module pins, live transistor tabs or terminals.','Install the PCB at box origin 9,9 mm and Z=9 mm. Hole centers are (13,13), (125,13), (13,125), (125,125) mm from the base origin. Use four M3 × 6 screws and 0.8 mm nylon washers.','Trim all solder tails to at most 3 mm below the PCB. H4 has specific relief pockets for R35 and D210; align the board correctly and confirm the tail clearances by dry fitting.','Dry fit all mating plugs, wire bends and strain relief with the unpowered board. Do not force a cable against the lid, a live transistor tab or the gasket. The CAD component envelope does not qualify the finished harness.',
'Fit the removable lid lining bond and its dielectric cover. Leave a flexible internal bond loop that cannot snag, touch electronics or cross the gasket.'])
new();heading('12 / splash resistance','Seal the lid and cable entries')
steps(['Cut one continuous ring from 2.0 mm soft closed-cell silicone sheet with the supplied 1:1 template. The ring is 3 mm wide; the groove is 3.4 mm wide and 1.5 mm deep. Do not print the reference gasket in ordinary rigid filament.','Inspect the sealing land, groove, case walls and layers for pores, strings and damage. Establish a compatible sealing/post-processing method if the printing process leaves porous walls.','Seat the ring without stretches, twists, gaps or adhesive lumps. The nominal geometry compresses a 2 mm sheet to 1.5 mm (25%); check the actual chosen material and print dimensions.','Fit four suitable M16 cable glands, or gasketed blanking plugs for unused holes. Their panel flange must fit the 24 mm diameter envelope. Use the manufacturer sealing washers and cable-jacket diameter range.','A single-hole gland seals against a round cable jacket, not a bundle of loose individual wires. Use appropriately jacketed multi-core harness groups and sealed external branches. The JST connectors are inside the box and are not sealed external bulkhead connectors.','Provide harness strain relief and a drip loop. Place cable entries away from direct splash and pooling. The rear entry centers are X=27,55,83,111 mm and Z=27 mm.','Close the lid with its drip skirt outside the base wall. Use eight M3 × 8 screws with 0.8 mm washers, tighten evenly and inspect continuous gasket seating. Screw holes lie outside the nominal water-seal line.','Test the empty assembled case with absorbent paper before installing electronics. Start with controlled light splashes in the intended orientations, inspect every seam and gland, dry completely, and correct leaks before repeating. No IP rating or pressure-wash/submersion capability is claimed.'])
note('Splash resistance, printed fit, insert strength, vibration, thermal behavior and shielding performance require physical tests. The CAD checks prove nominal solid/mesh integrity and specified clearances only. Keep all service work dry; opening the lid removes the splash barrier.')
section('Hardware list',['4 × M3 × 6 PCB screws and 0.8 mm nylon washers; 8 × M3 × 8 lid screws and 0.8 mm flat washers.','14 × ruthex RX-M3Sx4.0 short inserts: 4 PCB, 8 lid, 2 internal shield bonds. Check the actual insert datasheet and printed coupon.','2 × M3 × 5 bond screws with suitable ring terminals/star washers; H5 uses a separate M3 bolt/nut and short braid.','2 mm closed-cell silicone gasket sheet, conductive lining/bond materials, four matched M16 glands or sealed blanks.'])
new();heading('13 / acceptance record','Record the evidence for this build')
add('Complete this record for the actual board, harness and sensors. Blank fields mean not checked. A browser screenshot does not replace a measurement.','small')
table([['Item','Record / result'],['Board serial, PCB revision and assembly date','________________________________________________'],['Firmware environment / hash and profile revision','________________________________________________'],['12 V source, fuse and current-limit setting','________________________________________________'],['TP2 / TP3 / TP4 and measured U6 VREF','________________________________________________'],['Each sensor part number, actual pinout and curve source','________________________________________________'],['CLT/IAT pull-up values and independent temperature points','________________________________________________'],['MAP pressure reference / TPS travel reference points','________________________________________________'],['External wideband controller and analog-output mapping','________________________________________________'],['Crank/cam waveform, wheel pattern and air gap source','________________________________________________'],['CAN network state / termination / bitrate','________________________________________________'],['Printed material, gland/cable sizes and gasket material','________________________________________________'],['Dry fit, tail clearance, strain relief and bond continuity','________________________________________________'],['Empty-box splash test observations / orientation','________________________________________________'],['Outstanding faults and qualification work','________________________________________________']],[82*mm,94*mm])
section('Separate qualification still needed',['Measure reverse-polarity, supply transients/load dump, cranking brownout, regulator stability and thermal margins with suitable controlled equipment.','Qualify sensor fault stress, clamp currents, output current/clamp/thermal behavior and hardware inhibition on appropriate dummy loads.','Check EMC/immunity, grounding, harness interaction, vibration and environmental performance.','An actual vehicle ECU replacement needs a reviewed vehicle harness, complete engine control implementation and calibration, safety analysis and applicable emissions/legal assessment.'])
new();heading('14 / references','Files and manufacturer references')
add('The same structured guide content appears in the browser and in this manual. Keep the PDF, firmware, hardware and profile schema from the same release.','body')
for text in ['hardware/a3-compact/esp32-ecu.kicad_pcb and .kicad_sch: native design','hardware/a3-compact/bom.csv and connector-pinout.csv: assembly and pin contract','enclosure/a3/: STEP, STL, native FreeCAD, gasket/lining templates and dimensions','config/interface-guide.json: source of sensor mounting, checks and fault tracing','config/defaults.json: uncalibrated profile; schema version 1','docs/web-configuration.md: service setup, persistence and recovery','reports/web/: UI screenshots and automated software test results','reports/a3/: electrical CAD checks and dimensional audit']:
 add(text,'mono')
add('Guide source SHA-256: '+hashlib.sha256((R/'config/interface-guide.json').read_bytes()).hexdigest(),'small')
add('Primary references','h2')
