def footer(c,doc):
 c.saveState();c.setStrokeColor(line);c.line(17*mm,16*mm,193*mm,16*mm);c.setFont('Body',7);c.setFillColor(muted);c.drawString(17*mm,11*mm,'ECU STUDIO  /  A3-120  /  BENCH PROTOTYPE');c.drawRightString(193*mm,11*mm,f'{doc.page:02d}');c.restoreState()
class ManualDoc(SimpleDocTemplate):
 def afterFlowable(self,flowable):
  if isinstance(flowable,Paragraph) and flowable.style.name=='h1':
   key='chapter-'+str(self.page);self.canv.bookmarkPage(key);self.canv.addOutlineEntry(flowable.getPlainText(),key,0,False)
path=O/'esp32-ecu-a3-build-calibration-debug-manual.pdf';doc=ManualDoc(str(path),pagesize=(210*mm,297*mm),leftMargin=17*mm,rightMargin=17*mm,topMargin=17*mm,bottomMargin=22*mm,title='ESP32-S3 A3-120 - Build, calibration and connection diagnosis',author='ECU Studio engineering project')
doc.build(story,onFirstPage=footer,onLaterPages=footer);print(path)

